// Generated by voice-clone/sync_vo.py when a voiceover exists. null = no voiceover, script pacing.
export type VoWord = {w: string; start: number; end: number; beat: number};
export type VoBeat = {beat: number; start: number; end: number; text: string};
export const VO: null | {beats: (VoBeat & {cut?: number})[]; words: VoWord[]; total: number} = null;
